/* @author MILO-GAO(高振銘)@2020 */ package page2020.flow;import java.util.Set;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.core.App;import page2020.core.Flow;import page2020.core.Log;import page2020.core.Table;import page2020.unit.Ualert;import page2020.unit.Ubox;import page2020.util.EmptyUtil;import page2020.view.B4;import page2020.view.C3;import page2020.view.Child;import page2020.view.H5;import page2020.view.bs4.B4box;import page2020.view.bs4.B4color.Color;import page2020.view.bs4.B4element;import page2020.view.bs4.B4table;import page2020.view.css3.C3font.Weight;import page2020.view.css3.C3show.Overflow;public class TableFlow extends FormFlow {	private static Logger log = LoggerFactory.getLogger(TableFlow.class);	private int decorated = 0;	private int containers = 0;	private int boxes = 0;	@Override	public Flow automate() {		super.automate();		super.tables.forEach((name, child) -> this.wrap(child));		super.disableButtons("insert.outline", "update.outline", "delete.outline", "detail.outline");		Set<String> scripts = super.page.getScripts();		Set<String> sheets = super.page.getStylesheets();		boolean tableJS = false;		boolean dataApiJS = false;		boolean fixedColumnsJS = false;		boolean buttonsJS = false;		boolean datatableJS = false;		boolean pagingJS = false;		boolean verticalJS = false;				for (String key : super.tables.keySet()) {			Table table = (Table) super.tables.get(key).getContent();			if (table != null && table.getProp() != null) {				if (table.isDatatableJS()) {					dataApiJS = true;					if (table.getDatatable().isFixedColumnsJS()) {						fixedColumnsJS = true;					}										if (table.getDatatable().isButtonsJS()) {						buttonsJS = true;					}				}				if (table.isDatatableJS()) {					datatableJS = true;				}					if (table.isOperateJS()) {					super.operateJS = true;				}				tableJS = true;				if (table.isPagingJS()) {					pagingJS = true;				}				if (table.isVerticalJS()) {					verticalJS = true;				}							}		}		if (dataApiJS) {								scripts.add(Path.libs + "datatable/jquery.dataTables-1.10.23.min.js");			sheets.add(Path.libs + "datatable/dataTables.bootstrap4-1.10.23.min.css");			scripts.add(Path.libs + "datatable/dataTables.bootstrap4-1.10.23.min.js");		}		if (fixedColumnsJS) {			sheets.add(Path.libs + "datatable/fixedColumns.bootstrap4-3.3.2.min.css");			sheets.add(Path.libs + "datatable/scroller.bootstrap4-2.0.3.min.css");			scripts.add(Path.libs + "datatable/dataTables.fixedColumns-3.3.2.min.js");			scripts.add(Path.libs + "datatable/fixedColumns.bootstrap4-3.3.2.min.js");			scripts.add(Path.libs + "datatable/scroller.bootstrap4-2.0.3.min.js");			super.page.selector("div.DTFC_LeftBodyLiner, div.DTFC_RightBodyLiner",				C3.show.overflowX(Overflow.hidden));			super.page.selector("div.DTFC_RightHeadBlocker.DTFC_Blocker",				C3.bg("rgb(225,225,225)"));		}		if (buttonsJS) {			sheets.add(Path.libs + "datatable/buttons.bootstrap4-1.6.5.min.css");			scripts.add(Path.libs + "datatable/dataTables.buttons-1.6.5.min.js");			scripts.add(Path.libs + "datatable/buttons.bootstrap4-1.6.5.min.js");			scripts.add(Path.libs + "datatable/buttons.colVis-1.6.5.min.js");			scripts.add(Path.libs + "datatable/buttons.html5-1.6.5.min.js");			scripts.add(Path.libs + "datatable/buttons.print-1.6.5.min.js");			scripts.add(Path.libs + "datatable/jszip-2.5.0.min.js");		}		if (datatableJS) {			scripts.add(Path.page2020 + "datatable.js");		}			if (super.operateJS) {			scripts.add(Path.page2020 + "operate.js");		}		if (tableJS) {			scripts.add(Path.page2020 + "table.js");			super.page.message("page2020.confirm.delete");		}		if (pagingJS) {			scripts.add(Path.page2020 + "paging.js");		}		if (verticalJS) {			scripts.add(Path.page2020 + "vertical.js");							}		if (this.boxes > 0 && super.boxes == 0) {			scripts.add(Path.page2020 + "box.js");			Ubox.selector(super.page);		}		if (Log.flow) {			log.info(super.logName + "decorated=" + this.decorated + ", containers=" + this.containers);		}		return this;	}	private void wrap(Child child) {		Table table = (Table) child.getContent();		B4box<?> wrapper = B4.element();		if (table.isCaption()) {			B4element caption = B4.element()				.css(C3.font.size("1.1rem"), C3.font.weight(Weight.bold))				.append(H5.span().cssClass("mr-1").icon("database"))				.append(H5.code(App.classKey(table.getName())));			if (super.page.getHeaderColor() == null) {				caption.cssClass(Color.primary);			} else {				caption.css(C3.color(super.page.getHeaderColor()));			}			super.insert(child.getElement(), child.getIndex(), caption);		}		if (super.code == Code.row) {		 	super.insert(child.getElement(), child.getIndex(), new Ualert(table.getName()));		}		if (table.isDatatableJS()) {			super.insert(child.getElement(), child.getIndex(), table.getDatatable().automate());		}		wrapper.cssClass(B4table.responsive);		if (table.isDecorated()) {			wrapper.p(1);			wrapper.mb(2);			this.decorated += 1;		}		if (! table.isDatatableJS()) {			if (EmptyUtil.not(table.getHeight())) {				wrapper.css(C3.box.maxHeight(table.getHeight()));				wrapper.css(C3.show.overflow(Overflow.auto));							}		} else {			wrapper.css(C3.show.overflowX(Overflow.hidden));		}		wrapper.append(table);		if (table.isContainer()) {			wrapper = B4.container().append(wrapper);			this.containers += 1;		}		if (table.isPagingJS()) {			wrapper.append(table.getPaging());		}		if (table.getBox() != null) {			String name = super.page.getApp().getName();			wrapper = new Ubox(name, table.getBox(), wrapper);			this.boxes += 1;		}		child.getElement().set(child.getIndex(), wrapper);	}}